window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-997ca3f983e7f4d1"]={"versions": [{"id": "FIG-997ca3f983e7f4d1", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm (AUTOSAR Classic Platform BSW) zur Darstellung der Einbettung des IPduM (IPDU Multiplexer) innerhalb des AUTOSAR-Kommunikationsstacks. Gezeigt wird die vertikale und horizontale Einbindung des IPduM an den zentralen PDU Router sowie die Anbindung von AUTOSAR COM, Transportprotokollen (FlexRay TP, CAN TP) und Hardware-Abstraktionsschnittstellen (FlexRay Interface, CAN Interface, LIN Interface inkl. LIN TP).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>AUTOSAR COM</strong>: Oberste Kommunikationsschicht; tauscht I-PDUs bidirektional mit dem PDU Router aus.\n</li><li><strong>PDU Router (PduR)</strong>: Zentrale Vermittlungs- und Routing-Instanz für PDUs.\n</li><li><strong>IPDU multiplexer (IPduM)</strong>: Seitlich an den PDU Router angegliederte Komponente; kommuniziert ausschließlich bidirektional über I-PDU-Schnittstellen mit dem PDU Router.\n</li><li><strong>FlexRay TP</strong>: Transportprotokoll-Modul für FlexRay; empfängt und sendet I-PDUs zum PDU Router und N-PDUs zum FlexRay Interface.\n</li><li><strong>CAN TP</strong>: Transportprotokoll-Modul für CAN; empfängt und sendet I-PDUs zum PDU Router und N-PDUs zum CAN Interface.\n</li><li><strong>Communication HW Abstraction (grüner Layer)</strong>:\n<ul class=\"fig-list\"><li><strong>FlexRay Interface</strong>: Tauscht N-PDUs mit FlexRay TP sowie direkt I-PDUs mit dem PDU Router aus.\n</li><li><strong>CAN Interface</strong>: Tauscht N-PDUs mit CAN TP sowie direkt I-PDUs mit dem PDU Router aus.\n</li><li><strong>LIN Interface (incl. LIN TP)</strong>: Direkt bidirektional über I-PDU-Pfade mit dem PDU Router verbunden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sende-/Empfangspfad IPduM</strong>: Der IPduM interagiert nicht direkt mit BSW-Treibern oder COM, sondern empfängt und sendet I-PDUs ausschließlich über den PDU Router. Zu multiplexende oder demultiplexende I-PDUs werden vom PduR an den IPduM übergeben und nach der Verarbeitung wieder als I-PDUs an den PduR zurückgeleitet.\n</li><li><strong>Vertikaler Signal-/PDU-Fluss</strong>:\n<ul class=\"fig-list\"><li>Unsegmentierter Datenfluss erfolgt zwischen PduR und den Interfaces (FlexRay, CAN, LIN) direkt auf I-PDU-Ebene.\n</li><li>Segmentierter Datenfluss läuft vom PduR über die jeweiligen Transportprotokollmodule (FlexRay TP, CAN TP) als I-PDU und wird in N-PDUs transformiert an die Interfaces übergeben.\n</li><li>AUTOSAR COM übergibt und empfängt I-PDUs direkt vom PduR.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der IPduM ist als BSW-Modul konzipiert, das logisch neben dem PDU Router platziert ist und keine direkten Schnittstellen zur Hardware-Abstraktionsschicht oder zu AUTOSAR COM besitzt.\n</li><li>Sämtliche Ein- und Ausgangsdaten des IPduM sind formal als I-PDUs spezifiziert; das Multiplexing und Demultiplexing findet vollständig auf I-PDU-Ebene statt.\n</li><li>Für Entwickler bedeutet dies, dass alle Multiplex-Routen im PduR konfiguriert werden müssen (Routing-Pfade von COM/Interfaces zum IPduM und vom IPduM zurück zu Interfaces/COM).\n</li></ul>"}, {"id": "FIG-29b4881fbfed3d31", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm (AUTOSAR Classic Platform BSW) zur Darstellung der Einbettung des IPduM (IPDU Multiplexer) innerhalb des AUTOSAR-Kommunikationsstacks. Gezeigt wird die vertikale und horizontale Einbindung des IPduM an den zentralen PDU Router sowie die Anbindung von AUTOSAR COM, Transportprotokollen (FlexRay TP, CAN TP) und Hardware-Abstraktionsschnittstellen (FlexRay Interface, CAN Interface, LIN Interface inkl. LIN TP).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>AUTOSAR COM</strong>: Oberste Kommunikationsschicht; tauscht I-PDUs bidirektional mit dem PDU Router aus.\n</li><li><strong>PDU Router (PduR)</strong>: Zentrale Vermittlungs- und Routing-Instanz für PDUs.\n</li><li><strong>IPDU multiplexer (IPduM)</strong>: Seitlich an den PDU Router angegliederte Komponente; kommuniziert ausschließlich bidirektional über I-PDU-Schnittstellen mit dem PDU Router.\n</li><li><strong>FlexRay TP</strong>: Transportprotokoll-Modul für FlexRay; empfängt und sendet I-PDUs zum PDU Router und N-PDUs zum FlexRay Interface.\n</li><li><strong>CAN TP</strong>: Transportprotokoll-Modul für CAN; empfängt und sendet I-PDUs zum PDU Router und N-PDUs zum CAN Interface.\n</li><li><strong>Communication HW Abstraction (grüner Layer)</strong>:\n<ul class=\"fig-list\"><li><strong>FlexRay Interface</strong>: Tauscht N-PDUs mit FlexRay TP sowie direkt I-PDUs mit dem PDU Router aus.\n</li><li><strong>CAN Interface</strong>: Tauscht N-PDUs mit CAN TP sowie direkt I-PDUs mit dem PDU Router aus.\n</li><li><strong>LIN Interface (incl. LIN TP)</strong>: Direkt bidirektional über I-PDU-Pfade mit dem PDU Router verbunden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sende-/Empfangspfad IPduM</strong>: Der IPduM interagiert nicht direkt mit BSW-Treibern oder COM, sondern empfängt und sendet I-PDUs ausschließlich über den PDU Router. Zu multiplexende oder demultiplexende I-PDUs werden vom PduR an den IPduM übergeben und nach der Verarbeitung wieder als I-PDUs an den PduR zurückgeleitet.\n</li><li><strong>Vertikaler Signal-/PDU-Fluss</strong>:\n<ul class=\"fig-list\"><li>Unsegmentierter Datenfluss erfolgt zwischen PduR und den Interfaces (FlexRay, CAN, LIN) direkt auf I-PDU-Ebene.\n</li><li>Segmentierter Datenfluss läuft vom PduR über die jeweiligen Transportprotokollmodule (FlexRay TP, CAN TP) als I-PDU und wird in N-PDUs transformiert an die Interfaces übergeben.\n</li><li>AUTOSAR COM übergibt und empfängt I-PDUs direkt vom PduR.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der IPduM ist als BSW-Modul konzipiert, das logisch neben dem PDU Router platziert ist und keine direkten Schnittstellen zur Hardware-Abstraktionsschicht oder zu AUTOSAR COM besitzt.\n</li><li>Sämtliche Ein- und Ausgangsdaten des IPduM sind formal als I-PDUs spezifiziert; das Multiplexing und Demultiplexing findet vollständig auf I-PDU-Ebene statt.\n</li><li>Für Entwickler bedeutet dies, dass alle Multiplex-Routen im PduR konfiguriert werden müssen (Routing-Pfade von COM/Interfaces zum IPduM und vom IPduM zurück zu Interfaces/COM).\n</li></ul>"}], "trans": [{"from": "FIG-997ca3f983e7f4d1", "to": "FIG-29b4881fbfed3d31", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
